+package com.example;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(
+            "^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final MessageStore messageStore;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<MessageStore.Message> grid = new Grid<>();
+    private boolean resettingForm;
+    private boolean allowNavigation;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        H1 heading = new H1("Contact");
+        RouterLink about = new RouterLink("About", AboutView.class);
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone, message, send);
+        message.setWidthFull();
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(event -> fieldEdited(name));
+        email.addValueChangeListener(event -> fieldEdited(email));
+        phone.addValueChangeListener(event -> fieldEdited(phone));
+        message.addValueChangeListener(event -> fieldEdited(message));
+
+        grid.addColumn(MessageStore.Message::name).setHeader("Name");
+        grid.addColumn(MessageStore.Message::message).setHeader("Message");
+        grid.setItems(messageStore.getMessages());
+        grid.setWidthFull();
+
+        add(heading, about, form, grid);
+    }
+
+    private void fieldEdited(HasValidation field) {
+        if (!resettingForm) {
+            send.setEnabled(true);
+            field.setInvalid(false);
+        }
+    }
+
+    private void sendMessage() {
+        if (!validateForm()) {
+            return;
+        }
+
+        messageStore.add(name.getValue(), email.getValue(), phone.getValue(),
+                message.getValue());
+        grid.setItems(messageStore.getMessages());
+
+        resettingForm = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        resettingForm = false;
+        send.setEnabled(false);
+
+        com.vaadin.flow.component.notification.Notification
+                .show("Message sent");
+    }
+
+    private boolean validateForm() {
+        boolean valid = true;
+        String nameValue = name.getValue();
+        String emailValue = email.getValue();
+        String phoneValue = phone.getValue();
+        String messageValue = message.getValue();
+
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+
+        if (nameValue == null || nameValue.isBlank()) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            valid = false;
+        }
+
+        if (!emailValue.isBlank() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+            valid = false;
+        } else if (emailValue.isBlank() && phoneValue.isBlank()) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            valid = false;
+        }
+
+        if (messageValue == null || messageValue.isBlank()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            valid = false;
+        } else if (messageValue.length() > 500) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            message.setInvalid(true);
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (allowNavigation || !hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        Button keepEditing = new Button("Keep editing");
+        Button discard = new Button("Discard");
+
+        keepEditing.addClickListener(click -> {
+            dialog.close();
+            action.cancel();
+        });
+        discard.addClickListener(click -> {
+            allowNavigation = true;
+            dialog.close();
+            action.proceed();
+        });
+
+        dialog.add(new Span("You have unsent changes."),
+                new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+}
