+package com.example;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+
+@SpringBootTest(classes = Application.class)
+class ContactViewDiagnosticTest extends SpringBrowserlessTest {
+
+    @Test
+    void contactFlowWorks() {
+        navigate(ContactView.class);
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue(send.isEnabled());
+
+        test(send).click();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number",
+                email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("Hello");
+        fireShortcut(Key.ENTER);
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+
+        Grid<MessageStore.Message> grid = find(Grid.class).single();
+        assertEquals(1, test(grid).size());
+        assertEquals("Ada", test(grid).getRow(0).name());
+        assertEquals("Hello", test(grid).getRow(0).message());
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        assertEquals(1, test(find(Grid.class).single()).size());
+    }
+}
